import { describe, it, expect, beforeAll, afterAll } from "vitest";
import { prisma } from "@/lib/prisma";
import { POST, GET } from "@/app/api/posts/route";

describe("POST /api/posts (integration)", () => {
  it("creates a post in the database", async () => {
    const request = new Request("http://localhost/api/posts", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title: "Test", content: "Integration test content" }),
    });

    const response = await POST(request);
    expect(response.status).toBe(201);

    const { post } = await response.json();
    const saved = await prisma.post.findUnique({ where: { id: post.id } });
    expect(saved?.title).toBe("Test");
  });
});
